from pathlib import Path
import re

root = Path(__file__).parent
home = (root / 'index.html').read_text()
home_en = (root / 'en/index.html').read_text()
header = {
    'es': re.search(r'<header class="site-header.*?</header>', home).group(),
    'en': re.search(r'<header class="site-header.*?</header>', home_en).group(),
}
footer = {
    'es': re.search(r'<footer class="site-footer".*?</footer>', home).group(),
    'en': re.search(r'<footer class="site-footer".*?</footer>', home_en).group(),
}
styles = ''.join(re.findall(r'<link rel="stylesheet"[^>]+>', home))

icons = {
    'ship': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17h18l-3 4H6l-3-4ZM12 2v13M6 8h12l-2 7H8L6 8Z"/></svg>',
    'plane': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m2 16 8-3-6-7 2-1 8 6 6-2a2 2 0 0 1 2 2c0 1-.6 1.6-2 2l-6 2-3 9-2-1 1-8-8 3Z"/></svg>',
    'hotel': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 21V5h16v16M2 21h20M8 9h2m4 0h2M8 13h2m4 0h2M9 21v-4h6v4"/></svg>',
    'sun': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M19.1 4.9l-1.4 1.4M6.3 17.7l-1.4 1.4"/></svg>',
    'palm': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 9c-3-4-7-4-9-1 4-1 7 1 9 4m0-3c3-4 7-4 9-1-4-1-7 1-9 4m0-3c-2-5-1-7 2-8 0 3-1 5-2 8m0 2-2 11m2-11 3 11M5 22h14"/></svg>',
}

def page(lang, title, description, body, suffix=''):
    is_en = lang == 'en'
    nav = header[lang]
    foot = footer[lang]
    alternate = ('/en/dental-tourism/' if suffix == '/turismo-dental/' else '/turismo-dental/') if 'touris' in suffix or 'turismo' in suffix else ('/en/legal-notice/' if lang == 'es' else '/aviso-legal/')
    nav = re.sub(r'(<a class="language-option"[^>]*href=")[^"]+', lambda match: match.group(1) + alternate, nav, count=1)
    script = '<script src="/typewriter-titles.js?v=20261115b" defer></script><script src="/site-enhancements.js?v=20261115b" defer></script><script src="/tourism.js?v=20261115b" defer></script>'
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><meta name="theme-color" content="#142d48">{styles}<link rel="stylesheet" href="/typewriter-titles.css?v=20261115b"><link rel="stylesheet" href="/site-enhancements.css?v=20261115b"><link rel="stylesheet" href="/tourism.css?v=20261115b"><link rel="canonical" href="https://prontialatam.github.io{suffix}"></head><body>{nav}<div id="main-content">{body}</div>{foot}{script}</body></html>'''

def tab(index, icon, label):
    return f'<button type="button" role="tab" id="tourism-tab-{index}" aria-controls="tourism-panel-{index}" aria-selected="{str(index == 0).lower()}" tabindex="{0 if index == 0 else -1}">{icons[icon]}<span>{label}</span></button>'

months_es = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']
months_en = ['January','February','March','April','May','June','July','August','September','October','November','December']
temperatures = ['25,2','25,7','25,9','26,6','27,2','27,7','28,3','28,7','28,5','27,6','26,6','25,4']

def months(lang):
    labels = months_en if lang == 'en' else months_es
    return '<div class="tourism-months">' + ''.join(f'<div><span>{label}</span><strong>{value} °C</strong></div>' for label, value in zip(labels, temperatures)) + '</div>'

def airports(lang):
    data = [
        ('La Romana (LRM)','aeropuerto-la-romana.jpg','7 km','https://commons.wikimedia.org/wiki/File:La_Romana_Aeropuerto_RD.jpg','Wikimedia Commons · dominio público'),
        ('Punta Cana (PUJ)','aeropuerto-punta-cana.jpg','78 km','https://commons.wikimedia.org/wiki/File:Punta_Cana_International_Airport.jpg','Luculence · CC BY-SA 3.0'),
        ('Las Américas (SDQ)','aeropuerto-las-americas.jpg','85 km','https://commons.wikimedia.org/wiki/File:DOM_Boca_Chica,_Las_Am%C3%A9ricas_International_Airport_0001.jpg','-wuppertaler · CC BY 4.0'),
    ]
    return '<div class="tourism-airports">' + ''.join(f'<article class="tourism-airport"><img src="/images/turismo/{photo}" alt="{name}" loading="lazy"><div><h3>{name}</h3><strong>{distance} {"by road, approx." if lang == "en" else "por carretera, aprox."}</strong><p>{"Photo" if lang == "en" else "Foto"}: <a href="{source}" target="_blank" rel="noopener noreferrer">{license}</a></p></div></article>' for name, photo, distance, source, license in data) + '</div>'

def tourism_body(lang):
    en = lang == 'en'
    t = {
        'eyebrow':'IMPLANDENT · DENTAL TOURISM' if en else 'IMPLANDENT · TURISMO DENTAL',
        'hero':'Care for your <em>smile.</em> Discover La Romana.' if en else 'Cuida tu <em>sonrisa.</em> Descubre La Romana.',
        'hero_p':'Specialist dental care and Caribbean hospitality, thoughtfully planned around your visit.' if en else 'Atención odontológica especializada y hospitalidad caribeña, planificadas alrededor de tu visita.',
        'cta':'Plan your visit' if en else 'Planifica tu visita',
        'illustration':'Illustrative image generated for this website' if en else 'Imagen ilustrativa creada para esta web',
        'intro_title':'A destination for your <em>wellbeing.</em>' if en else 'Un destino para tu <em>bienestar.</em>',
        'intro_1':'Dental tourism brings together an individualized clinical plan and a stay away from home. At Implandent, Dr. Miguel Ángel Carela Gutiérrez and the team can assess your case, explain treatment phases, estimate appointments and coordinate timing before you travel.' if en else 'El turismo dental combina una planificación clínica individual con una estancia fuera de tu lugar de residencia. En Implandent, el Dr. Miguel Ángel Carela Gutiérrez y su equipo pueden valorar tu caso, explicar las fases del tratamiento y coordinar los tiempos antes del viaje.',
        'intro_2':'The Dominican Republic attracts international patients for its trained dental professionals, the possibility of competitive costs and its world-renowned holiday setting. Every quote and treatment plan is personalized; travel and accommodation are arranged separately.' if en else 'La República Dominicana atrae a pacientes internacionales por la formación de sus profesionales odontológicos, la posibilidad de costes competitivos y su atractivo vacacional. Cada presupuesto y plan de tratamiento se personaliza; el viaje y el alojamiento se gestionan por separado.',
        'doctor_title':'Meet Dr. <em>Carela.</em>' if en else 'Conoce al Dr. <em>Carela.</em>',
        'doctor_intro':'Oral implant specialist and CEO of Implandent since 2021.' if en else 'Especialista en implantología oral y CEO de Implandent desde 2021.',
        'bio':'Full biography' if en else 'Biografía completa',
        'guide_title':'Explore your stay in <em>La Romana.</em>' if en else 'Explora tu estancia en <em>La Romana.</em>',
        'guide_p':'Five practical guides to help you plan a visit with confidence.' if en else 'Cinco guías prácticas para organizar tu visita con tranquilidad.',
        'tabs':['La Romana','Airports','Accommodation','Climate','Casa de Campo'] if en else ['La Romana','Aeropuertos','Alojamiento','Clima','Casa de Campo'],
    }
    bio_es = [
        'Mi nombre es Miguel Ángel Carela Gutiérrez. Soy odontólogo graduado de la Universidad Central del Este el 25 de febrero de 2011.',
        'Me especialicé en implantología oral en el Centro Médico UCE y me gradué en 2019.',
        'Durante mi formación académica he realizado diplomados en injertos óseos orales, prótesis sobre implantes dentales e implantología estratégica corticobasal, entre otros.',
        'Soy CEO de la Clínica Odontológica Especializada Implandent desde 2021.',
        'Soy miembro activo del Colegio Dominicano de Odontólogos (CDO) y de la Sociedad Dominicana de Implantología Oral (SDIO).',
    ]
    bio_en = [
        'My name is Miguel Ángel Carela Gutiérrez. I graduated in dentistry from Universidad Central del Este on February 25, 2011.',
        'I specialized in oral implantology at Centro Médico UCE and graduated in 2019.',
        'During my academic training, I completed courses in oral bone grafting, implant-supported prosthetics and strategic corticobasal implantology, among others.',
        'I have been CEO of Clínica Odontológica Especializada Implandent since 2021.',
        'I am an active member of Colegio Dominicano de Odontólogos (CDO) and Sociedad Dominicana de Implantología Oral (SDIO).',
    ]
    bio = ''.join(f'<p>{p}</p>' for p in (bio_en if en else bio_es))
    tabs = ''.join(tab(i, ['ship','plane','hotel','sun','palm'][i], label) for i,label in enumerate(t['tabs']))
    source = lambda url,text: f'<p class="tourism-source">{"Source" if en else "Fuente"}: <a href="{url}" target="_blank" rel="noopener noreferrer">{text}</a></p>'
    romana = f'''<div class="tourism-feature"><div class="tourism-image"><img src="/images/turismo/puerto-la-romana.jpg" alt="{'Aerial view of a cruise ship docked in La Romana port' if en else 'Vista aérea de un crucero atracado en el puerto de La Romana'}" loading="lazy"></div><div><h3>{'A city with its own rhythm.' if en else 'Una ciudad con ritmo propio.'}</h3><p>{'La Romana is a gateway to Caribbean landscapes and Dominican culture. Its cruise port welcomes travelers, while Altos de Chavón, local galleries and nearby excursions offer ways to enjoy the area between appointments.' if en else 'La Romana es una puerta de entrada al Caribe y a la cultura dominicana. Su puerto recibe cruceros, mientras Altos de Chavón, las galerías y las excursiones cercanas ofrecen planes para disfrutar la zona entre citas.'}</p>{source('https://www.godominicanrepublic.com/destinations/la-romana?lang=en','Turismo República Dominicana')}{source('https://portuaria.gob.do/data-historica/www.transparencia.portuaria.gob.do/file-download/download/public/Puertos%20Comerciales%20RD%202018.pdf','Autoridad Portuaria Dominicana · foto del puerto')}</div></div>'''
    airport_info = f'<p>{"Approximate road distances to La Romana city; the journey varies by route and traffic." if en else "Distancias aproximadas por carretera hasta la ciudad de La Romana; el recorrido varía según la ruta y el tráfico."} <a href="https://www.rome2rio.com/s/La-Romana/Punta-Cana-Airport-Dominican-Republic" target="_blank" rel="noopener noreferrer">{"Route reference" if en else "Referencia de rutas"}</a>.</p>'
    lodging = f'''<div class="tourism-feature"><div class="tourism-image"><img src="/images/turismo/hilton-garden-inn.jpg" alt="Hilton Garden Inn La Romana" loading="lazy"></div><div><h3>Hilton Garden Inn La Romana</h3><p>{'A midrange seafront option with a pool, restaurant, bars, fitness center, free Wi-Fi and parking. Its location is convenient for visiting the city.' if en else 'Una opción de categoría media frente al mar, con piscina, restaurante, bares, gimnasio, wifi y estacionamiento. Su ubicación facilita las visitas a la ciudad.'}</p><span class="tourism-rate">{'Official 2026 rate from US$121/night' if en else 'Tarifa oficial 2026 desde US$121/noche'}</span><p>{'Indicative double-room starting rate shown by Hilton on November 14, 2026. Hilton does not publish a verified annual average; dates, taxes and availability change the final price.' if en else 'Tarifa inicial orientativa para habitación doble mostrada por Hilton el 14 de noviembre de 2026. Hilton no publica una media anual verificable; fechas, impuestos y disponibilidad cambian el precio final.'}</p>{source('https://www.hilton.com/en/hotels/lrmlmgi-hilton-garden-inn-la-romana/','Hilton · hotel y fotografía')}{source('https://www.hilton.com/en/locations/dominican-republic/la-romana/hilton-garden-inn/','Hilton · tarifas publicadas')}</div></div>'''
    climate = f'''<p>{'Measured monthly mean air temperature (2 m) near La Romana for calendar year 2025, according to NASA POWER. These are historical values, not a forecast.' if en else 'Temperatura media mensual del aire a 2 m cerca de La Romana durante 2025, según NASA POWER. Son valores históricos, no una previsión.'}</p>{months(lang)}{source('https://power.larc.nasa.gov/api/temporal/monthly/point?parameters=T2M&community=AG&longitude=-68.9654&latitude=18.4227&format=JSON&start=2025&end=2025','NASA POWER · 2025') }'''
    casa = f'''<div class="tourism-feature"><div class="tourism-image"><img src="/images/turismo/casa-de-campo.jpg" alt="Casa de Campo Marina, La Romana" loading="lazy"></div><div><h3>Casa de Campo</h3><p>{'This private resort in La Romana brings together villas and hotel rooms, Minitas Beach, a marina, golf courses, restaurants, a spa and sports facilities.' if en else 'Este complejo privado de La Romana reúne villas y habitaciones de hotel, Playa Minitas, marina, campos de golf, restaurantes, spa y actividades deportivas.'}</p><span class="tourism-rate">{'Official fall 2026 offer from US$375/night' if en else 'Oferta oficial otoño 2026 desde US$375/noche'}</span><p>{'Rooms and suites starting rate in the official fall 2026 promotion, valid for stays October 1–December 20, 2026; taxes, conditions and availability apply. No official annual average is published.' if en else 'Tarifa inicial de habitaciones y suites en la promoción oficial de otoño 2026, válida para estancias del 1 de octubre al 20 de diciembre de 2026; sujeta a condiciones, impuestos y disponibilidad. No se publica una media anual oficial.'}</p>{source('https://www.casadecampo.com.do/vacation-packages-offers/fall-savings/','Casa de Campo · oferta 2026')}{source('https://commons.wikimedia.org/wiki/File:Casa_de_Campo_Marina,_La_Romana_22000,_Dominican_Republic_-_panoramio.jpg','Максим Улитин · CC BY 3.0')}</div></div>'''
    panels = [romana, airports(lang)+airport_info, lodging, climate, casa]
    panels_html = ''.join(f'<section role="tabpanel" id="tourism-panel-{i}" aria-labelledby="tourism-tab-{i}" class="tourism-panel"{ " hidden" if i else ""}>{content}</section>' for i,content in enumerate(panels))
    whatsapp = 'https://wa.me/18099365539?text=' + ('Hello%2C%20I%20would%20like%20to%20plan%20a%20dental%20tourism%20visit%20to%20Implandent.' if en else 'Hola%2C%20deseo%20planificar%20una%20visita%20de%20turismo%20dental%20a%20Implandent.')
    return f'''<main class="tourism-page"><section class="tourism-hero"><div class="tourism-wrap tourism-hero-inner"><span class="tourism-eyebrow">{t['eyebrow']}</span><h1>{t['hero']}</h1><p>{t['hero_p']}</p><a class="button button-whatsapp" href="{whatsapp}" target="_blank" rel="noopener noreferrer">{t['cta']} ↗</a></div><span class="tourism-photo-note">{t['illustration']}</span></section><section class="tourism-intro tourism-wrap"><div class="tourism-intro-grid"><h2>{t['intro_title']}</h2><div><p>{t['intro_1']}</p><p>{t['intro_2']}</p></div></div></section><section class="tourism-doctor"><div class="tourism-wrap tourism-doctor-grid"><div class="tourism-doctor-photo"><img src="/images/dr-carela-portrait.jpeg" alt="Dr. Miguel Ángel Carela Gutiérrez" loading="lazy"></div><div><span class="tourism-eyebrow">IMPLANDENT · LA ROMANA</span><h2>{t['doctor_title']}</h2><p>{t['doctor_intro']}</p><details><summary>{t['bio']}</summary><div class="tourism-doctor-bio">{bio}</div></details></div></div></section><section class="tourism-guide tourism-wrap"><div class="tourism-guide-heading"><div><span class="tourism-eyebrow">{t['eyebrow']}</span><h2>{t['guide_title']}</h2></div><p>{t['guide_p']}</p></div><div class="tourism-tabs" role="tablist" aria-label="{'Dental tourism guide' if en else 'Guía de turismo dental'}">{tabs}</div>{panels_html}</section><section class="tourism-cta"><div class="tourism-wrap"><span class="tourism-eyebrow">IMPLANDENT · LA ROMANA</span><h2>{'Your next step starts with a conversation.' if en else 'El siguiente paso empieza con una conversación.'}</h2><p>{'Tell us what care you need and when you plan to travel. The team will guide you through clinical assessment and scheduling.' if en else 'Cuéntanos qué atención necesitas y cuándo planeas viajar. El equipo te orientará sobre la valoración clínica y las citas.'}</p><a class="button button-whatsapp" href="{whatsapp}" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a></div></section></main>'''

